311	// hooks/useCounter.ts
312	import { useState, useCallback } from "react";
313	
314	export function useCounter(initialValue = 0) {
315	  const [count, setCount] = useState(initialValue);
316	
317	  const increment = useCallback(() => setCount((c) => c + 1), []);
318	  const decrement = useCallback(() => setCount((c) => c - 1), []);
319	  const reset = useCallback(() => setCount(initialValue), [initialValue]);
320	
321	  return { count, increment, decrement, reset };
322	}
